source='''def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    runs = []
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] == bg:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] != bg:
                c += 1
            if c - start >= 2:
                runs.append((c-start, 'h', r, start, [grid[r][x] for x in range(start,c)]))
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] == bg:
                r += 1
                continue
            start = r
            while r < h and grid[r][c] != bg:
                r += 1
            if r - start >= 2:
                runs.append((r-start, 'v', start, c, [grid[x][c] for x in range(start,r)]))
    _, orient, r0, c0, pattern = max(runs, key=lambda q:q[0])
    motif_cells = {(r0,c0+i) if orient=='h' else (r0+i,c0) for i in range(len(pattern))}
    counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                     if grid[r][c] != bg and (r,c) not in motif_cells)
    trigger = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]
    anchor = len(pattern)//2
    for r in range(h):
        for c in range(w):
            if grid[r][c] != trigger:
                continue
            for i, val in enumerate(pattern):
                rr, cc = ((r, c+i-anchor) if orient=='h' else (r+i-anchor, c))
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = val
    return out
'''
